import styled from '@emotion/styled';
import { theme } from 'theme';

import { SEGMENTED_CONTROL_SELECTED_SHADOW } from './SegmentedControl.constants';

export const StyledGroup = styled('div')({
  backgroundColor: theme.colors.interfaceSurfacePrimary,
  borderRadius: '9999px',
  display: 'flex',
  maxHeight: '2.5rem',
  minHeight: '2.5rem',
  width: 'min-content',
});

export const StyledItem = styled('button')({
  alignItems: 'center',
  backgroundColor: 'transparent',
  border: 'none',
  borderRadius: '9999px',
  cursor: 'pointer',
  display: 'flex',
  justifyContent: 'center',
  maxHeight: '2.5rem',
  paddingLeft: theme.spacing['4'],
  paddingRight: theme.spacing['4'],
  '&[aria-checked="true"], &[data-state="on"]': {
    backgroundColor: theme.colors.neutral0,
    borderRadius: '9999px',
    boxShadow: SEGMENTED_CONTROL_SELECTED_SHADOW,
    '& > span': {
      color: theme.colors.interfaceLabelPrimary,
    },
  },
  '&:disabled': {
    cursor: 'not-allowed',
    opacity: 0.5,
  },
  '&:focus-visible': {
    outline: `2px solid ${theme.colors.semanticInfoText}`,
    outlineOffset: '2px',
  },
});

export const StyledLabel = styled('span')({
  color: theme.colors.interfaceLabelSecondary,
  cursor: 'pointer',
  fontFamily: theme.fonts.paragraph,
  fontSize: theme.fonts.fontSizes['2'],
  fontWeight: theme.fonts.fontWeights.medium,
  lineHeight: theme.fonts.lineHeights['3'],
  userSelect: 'none',
  whiteSpace: 'nowrap',
});
